module clock_divider (
    input clk,
    input rst,
    output reg clk_out
);
    reg [1:0] counter;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 2'b00;
            clk_out <= 0;
        end else begin
            counter <= counter + 1;
            if (counter == 2'b11) begin
                clk_out <= ~clk_out;
                counter <= 2'b00;
            end
        end
    end
endmodule

