module kalman_filter #(parameter DATA_WIDTH = 16)  
(  
    input clk,  
    input rst,  
    input [DATA_WIDTH-1:0] measurement,  
    output reg [DATA_WIDTH-1:0] estimate  
);  
    reg [DATA_WIDTH-1:0] prev_estimate;  
    reg [DATA_WIDTH-1:0] kalman_gain;  
    reg [DATA_WIDTH-1:0] process_noise = 16'h0001;  
    reg [DATA_WIDTH-1:0] measurement_noise = 16'h0002;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            estimate <= 16'h0000;  
            prev_estimate <= 16'h0000;  
            kalman_gain <= 16'h0000;  
        end else begin  
            kalman_gain <= prev_estimate / (prev_estimate + measurement_noise);  
            estimate <= prev_estimate + kalman_gain * (measurement - prev_estimate);  
            prev_estimate <= estimate;  
        end  
    end  
endmodule

