module I2C_Master (  
    input wire clk,  
    input wire rst,  
    input wire enable,  
    output reg SDA,  
    output reg SCL  
);  
    reg [3:0] state;  
    parameter IDLE = 4'b0000, START = 4'b0001, ADDRESS = 4'b0010, ACK = 4'b0011, STOP = 4'b0100;  
    reg [7:0] address;  
    reg [3:0] bit_count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            SDA <= 1;  
            SCL <= 1;  
            address <= 8'b10100000;  // Example address  
            bit_count <= 0;  
        end else if (enable) begin  
            case (state)  
                IDLE: begin  
                    SDA <= 1;  
                    SCL <= 1;  
                    state <= START;  
                end  
                START: begin  
                    SDA <= 0;  
                    state <= ADDRESS;  
                end  
                ADDRESS: begin  
                    if (bit_count < 8) begin  
                        SDA <= address[7 - bit_count];  
                        SCL <= 0;  
                        bit_count <= bit_count + 1;  
                        state <= ACK;  
                    end else begin  
                        bit_count <= 0;  
                        state <= STOP;  
                    end  
                end  
                ACK: begin  
                    SCL <= 1;  
                    SDA <= 1;  // Acknowledge from slave  
                    state <= ADDRESS;  
                end  
                STOP: begin  
                    SDA <= 0;  
                    SCL <= 1;  
                    SDA <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

