module master_slave_d_latch(  
    input wire D,  
    input wire CLK,  
    input wire EN,  
    output reg Q  
);  
    reg master;  
    always @(posedge CLK) begin  
        if (EN)  
            master <= D;  
    end  
    always @(negedge CLK) begin  
        if (EN)  
            Q <= master;  
    end  
endmodule

