module floyd_warshall #(parameter N = 4, parameter INF = 16'hFFFF) (  
    input clk,  
    input rst,  
    input start,  
    input [N*N*16-1:0] graph,  
    output reg [N*N*16-1:0] dist,  
    output reg done  
);  

    reg [3:0] k;  
    reg [3:0] i;  
    reg [3:0] j;  
    reg [N*N*16-1:0] next_dist;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            dist <= graph;  
            k <= 0;  
            done <= 0;  
        end else if (start) begin  
            if (k < N) begin  
                for (i = 0; i < N; i = i + 1) begin  
                    for (j = 0; j < N; j = j + 1) begin  
                        if (dist[i*N + j] > dist[i*N + k] + dist[k*N + j]) begin  
                            next_dist[i*N + j] = dist[i*N + k] + dist[k*N + j];  
                        end else begin  
                            next_dist[i*N + j] = dist[i*N + j];  
                        end  
                    end  
                end  
                dist <= next_dist;  
                k <= k + 1;  
            end else begin  
                done <= 1;  
            end  
        end  
    end  
endmodule

