module mpc_controller (
    input wire clk,
    input wire reset,
    input wire [7:0] error,
    output reg [7:0] control_signal
);
    reg [7:0] error_history [0:3];
    integer i;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            control_signal <= 8'b0;
            for (i = 0; i < 4; i = i + 1) begin
                error_history[i] <= 8'b0;
            end
        end else begin
            // Shift history
            for (i = 3; i > 0; i = i - 1) begin
                error_history[i] <= error_history[i-1];
            end
            error_history[0] <= error;
            // Simple proportional control: sum of errors for control output
            control_signal <= error_history[0] + error_history[1] + error_history[2] + error_history[3];
        end
    end
endmodule

