module watchdog_timer (  
    input wire clk,  
    input wire reset_n,  
    input wire input_signal,  
    output reg reset_signal  
);  
    parameter TIME_LIMIT = 8'd100;  // Define time limit for the watchdog timer  
    reg [7:0] counter;  // 8-bit counter for the timer  
    reg timer_running;  // Flag to indicate if the timer is running  

    always @(posedge clk or negedge reset_n) begin  
        if (!reset_n) begin  
            counter <= 8'd0;  
            reset_signal <= 1'b0;  
            timer_running <= 1'b0;  
        end else begin  
            if (input_signal) begin  
                counter <= 8'd0;  // Reset counter when input is high  
                timer_running <= 1'b1;  
            end else if (timer_running) begin  
                counter <= counter + 1;  
                if (counter >= TIME_LIMIT) begin  
                    reset_signal <= 1'b1;  // Trigger reset signal after timeout  
                    timer_running <= 1'b0;  
                end else begin  
                    reset_signal <= 1'b0;  
                end  
            end  
        end  
    end  
endmodule

