module restoring_divider(clk, rst, start, dividend, divisor, quotient, remainder, done);  
    input clk, rst, start;  
    input [4:0] dividend;  
    input [2:0] divisor;  
    output reg [2:0] quotient;  
    output reg [1:0] remainder;  
    output reg done;  

    reg [4:0] temp_dividend;  
    reg [2:0] temp_divisor;  
    reg [2:0] count;  
    reg [1:0] state;  

    parameter IDLE = 2'b00, DIVIDE = 2'b01, DONE = 2'b10;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 3'b000;  
            quotient <= 3'b000;  
            remainder <= 2'b00;  
            done <= 0;  
            state <= IDLE;  
        end  
        else begin  
            case (state)  
                IDLE: begin  
                    if (start) begin  
                        temp_dividend <= dividend;  
                        temp_divisor <= divisor;  
                        count <= 3'b000;  
                        state <= DIVIDE;  
                    end  
                end  
                DIVIDE: begin  
                    if (count < 3) begin  
                        temp_dividend = {temp_dividend[3:0], 1'b0};  
                        if (temp_dividend >= {2'b00, temp_divisor}) begin  
                            temp_dividend = temp_dividend - {2'b00, temp_divisor};  
                            quotient[count] = 1;  
                        end  
                        count <= count + 1;  
                    end  
                    else begin  
                        remainder <= temp_dividend[1:0];  
                        state <= DONE;  
                    end  
                end  
                DONE: begin  
                    done <= 1;  
                end  
            endcase  
        end  
    end  
endmodule

