module serializer (  
    input wire clk,  
    input wire start,  
    input wire [7:0] parallel_in,  
    output reg serial_out  
);  
    reg [2:0] bit_count;  
    always @(posedge clk) begin  
        if (start) begin  
            bit_count <= 0;  
        end else if (bit_count < 8) begin  
            serial_out <= parallel_in[7 - bit_count];  
            bit_count <= bit_count + 1;  
        end  
    end  
endmodule

