module uart_transmitter(  
    input wire clk,  
    input wire start,  
    input wire [7:0] data,  
    output reg tx,  
    output reg ready  
);  
    reg [3:0] bit_count;  
    reg [9:0] shift_reg; // 8 data bits + start + stop bit  
    reg state;  
    localparam IDLE = 1'b0, TRANSMIT = 1'b1;  
    always @(posedge clk) begin  
        case(state)  
            IDLE: begin  
                tx <= 1; // Idle state is '1'  
                ready <= 1;  
                if (start) begin  
                    shift_reg <= {1'b1, data, 1'b0}; // Stop bit at the end, start bit at the front  
                    bit_count <= 0;  
                    state <= TRANSMIT;  
                    ready <= 0;  
                end  
            end  
            TRANSMIT: begin  
                tx <= shift_reg[0];  
                shift_reg <= shift_reg >> 1;  
                bit_count <= bit_count + 1;  
                if (bit_count == 9) begin // After sending 10 bits (8 data + start + stop)  
                    state <= IDLE;  
                end  
            end  
        endcase  
    end  
endmodule

