module fractional_n_pll (
    input wire clk_ref,
    input wire reset,
    input wire [7:0] N, // Integer part of the division
    input wire [7:0] Frac, // Fractional part of the division
    output reg clk_out
);

reg [15:0] counter_int;
reg [15:0] counter_frac;
reg [7:0] fractional_divider;

always @(posedge clk_ref or posedge reset) begin
    if (reset) begin
        counter_int <= 0;
        counter_frac <= 0;
        clk_out <= 0;
    end else begin
        counter_int <= counter_int + 1;
        if (counter_int >= N) begin
            counter_int <= 0;
            clk_out <= ~clk_out;
            fractional_divider <= (Frac > 0) ? (counter_frac + 1) : 0;
            if (fractional_divider >= Frac) begin
                fractional_divider <= 0;
                clk_out <= ~clk_out;
            end
        end
    end
end

endmodule

