module interrupt_controller(
    input wire [3:0] IRQ,
    input wire [1:0] PRIO,
    input wire INT_CLEAR,
    output reg INT_ACK
);
    reg [3:0] active_irq;

    always @(posedge INT_CLEAR or posedge IRQ[3] or posedge IRQ[2] or posedge IRQ[1] or posedge IRQ[0]) begin
        if (INT_CLEAR) begin
            INT_ACK <= 0;
            active_irq <= 4'b0000;
        end else begin
            active_irq <= IRQ;
            case (PRIO)
                2'b00: INT_ACK <= active_irq[0]; // Highest Priority
                2'b01: INT_ACK <= active_irq[1];
                2'b10: INT_ACK <= active_irq[2];
                2'b11: INT_ACK <= active_irq[3]; // Lowest Priority
                default: INT_ACK <= 0;
            endcase
        end
    end
endmodule

