module spi_master (
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [4:0] command,
    output reg cs,
    output reg sck,
    output reg mosi,
    input wire miso,
    output reg [4:0] response
);

    reg [2:0] state;
    reg [2:0] next_state;
    reg [2:0] bit_count;

    parameter IDLE = 3'b000,
              SEND = 3'b001,
              RECEIVE = 3'b010,
              DONE = 3'b011;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case(state)
            IDLE: begin
                cs = 1;
                sck = 0;
                if (enable) begin
                    next_state = SEND;
                end else begin
                    next_state = IDLE;
                end
            end
            SEND: begin
                cs = 0;
                if (bit_count < 5) begin
                    mosi = command[4 - bit_count]; // Send command LSB first
                    sck = 1;
                    next_state = RECEIVE;
                end else begin
                    next_state = DONE;
                end
            end
            RECEIVE: begin
                sck = 1;
                if (bit_count < 5) begin
                    response[4 - bit_count] = miso; // Receive response LSB first
                    bit_count = bit_count + 1;
                end else begin
                    next_state = DONE;
                end
            end
            DONE: begin
                cs = 1;
                sck = 0;
                next_state = IDLE;
                bit_count = 0; // Reset for next command
            end
            default: next_state = IDLE;
        endcase
    end
endmodule

