module dma_controller(
    input clk,
    input reset,
    input start,
    input [7:0] src_addr,
    input [7:0] dest_addr,
    input [3:0] transfer_count,
    output reg done
);
    reg [3:0] count;
    reg [7:0] current_src;
    reg [7:0] current_dest;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            done <= 0;
            count <= 0;
            current_src <= 0;
            current_dest <= 0;
        end else if (start) begin
            current_src <= src_addr;
            current_dest <= dest_addr;
            count <= transfer_count;
            done <= 0;
        end else if (count > 0) begin
            // Simulate data transfer
            current_src <= current_src + 1; // Move to next source address
            current_dest <= current_dest + 1; // Move to next destination address
            count <= count - 1; // Decrement transfer count
        end else begin
            done <= 1; // Transfer is done
        end
    end
endmodule

