module EchoCancellation (
    input wire clk,
    input wire reset,
    input wire signed [15:0] x,      // Input signal
    input wire signed [15:0] d,      // Desired signal (reference)
    output reg signed [15:0] y       // Output signal
);
    reg signed [15:0] w [0:4];        // Filter coefficients
    reg signed [15:0] x_reg [0:4];    // Input signal delay line
    integer i;

    // Initialize filter coefficients
    initial begin
        w[0] = 16'h0001; // Coefficient for previous input sample
        w[1] = 16'h0001; // You can modify these values for better echo cancellation
        w[2] = 16'h0001;
        w[3] = 16'h0001;
        w[4] = 16'h0001;
    end

    // Process the input signal and apply the FIR filter
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            y <= 16'h0000; // Reset output
            for (i = 0; i < 5; i = i + 1)
                x_reg[i] <= 16'h0000; // Reset delay line
        end else begin
            // Shift input signal through delay line
            x_reg[0] <= x;
            for (i = 1; i < 5; i = i + 1) begin
                x_reg[i] <= x_reg[i-1];
            end

            // Perform the filtering operation
            y <= (w[0] * x_reg[0] + w[1] * x_reg[1] + 
                   w[2] * x_reg[2] + w[3] * x_reg[3] + 
                   w[4] * x_reg[4]) >>> 4; // Right shift for normalization
        end
    end
endmodule

