module non_restoring_divider(
    input clk,
    input rst,
    input [7:0] dividend,
    input [7:0] divisor,
    output reg [7:0] quotient,
    output reg [7:0] remainder,
    output reg done
);
    reg [7:0] A; // Accumulator
    reg [7:0] Q; // Quotient
    reg [7:0] M; // Divisor
    reg [3:0] count; // Count for iterations
    reg state; // State for done signal

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            A <= 8'b0;
            Q <= 8'b0;
            M <= divisor;
            count <= 4'b0;
            done <= 1'b0;
            state <= 1'b0;
        end else if (count < 8) begin
            if (state == 0) begin
                A <= {A[6:0], Q[7]}; // Shift A
                A <= A - M; // Subtract M from A
                if (A[7] == 1) begin // If A is negative
                    A <= A + M; // Restore A
                    Q <= {Q[6:0], 1'b0}; // Shift Q and append 0
                end else begin
                    Q <= {Q[6:0], 1'b1}; // Shift Q and append 1
                end
            end else begin
                // Final steps
                remainder <= A;
                quotient <= Q;
                done <= 1'b1;
            end
            count <= count + 1;
        end
    end
endmodule

