module adaptive_lms_filter #(parameter N = 5, parameter mu = 8'h01)  
(  
    input clk,  
    input rst,  
    input signed [15:0] x, // input signal  
    input signed [15:0] d, // desired output  
    output reg signed [15:0] y // output signal  
);  
    reg signed [15:0] w [0:N-1]; // filter coefficients  
    reg signed [15:0] e; // error signal  
    integer i;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            // Initialize weights to zero  
            for (i = 0; i < N; i = i + 1)  
                w[i] <= 16'sd0;  
            y <= 16'sd0;  
        end else begin  
            // Calculate output  
            y <= 16'sd0;  
            for (i = 0; i < N; i = i + 1)  
                y <= y + (w[i] * x);  

            // Calculate error  
            e <= d - y;  

            // Update weights  
            for (i = 0; i < N; i = i + 1)  
                w[i] <= w[i] + (mu * e * x);  
        end  
    end  
endmodule

