module restoring_divider(
    input [4:0] dividend,
    input [2:0] divisor,
    input clk,
    input start,
    output reg [4:0] quotient,
    output reg done
);
    reg [4:0] remainder;
    reg [2:0] count;
    reg [1:0] state;

    localparam IDLE = 2'b00, DIVIDE = 2'b01, DONE = 2'b10;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                if (start) begin
                    quotient <= 5'b0;
                    remainder <= dividend;
                    count <= 3'b101; // divisor's size
                    state <= DIVIDE;
                    done <= 1'b0;
                end
            end

            DIVIDE: begin
                if (count > 0) begin
                    remainder <= {remainder[3:0], 1'b0} - {2'b00, divisor}; // Shift and subtract
                    quotient <= {quotient[3:0], remainder[4] ? 1'b0 : 1'b1}; // Set the quotient bit

                    if (remainder[4]) // If remainder is negative
                        remainder <= {remainder[3:0], 1'b0}; // Restore remainder
                    count <= count - 1;
                end else begin
                    state <= DONE;
                end
            end

            DONE: begin
                done <= 1'b1;
                state <= IDLE;
            end
        endcase
    end
endmodule

