module adaptive_lms_filter #(parameter N = 5, parameter STEP_SIZE = 8'h01)  
(  
    input clk,  
    input reset,  
    input signed [15:0] x, // Input signal  
    input signed [15:0] d, // Desired signal  
    output signed [15:0] y // Output signal  
);  
    reg signed [15:0] w [0:N-1]; // Filter weights  
    reg signed [15:0] y_reg; // Output signal  
    reg signed [15:0] e; // Error signal  
    integer i;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            for (i = 0; i < N; i = i + 1) begin  
                w[i] <= 16'b0;  
            end  
            y_reg <= 16'b0;  
        end else begin  
            e <= d - y_reg;  
            y_reg <= 0;  
            for (i = 0; i < N; i = i + 1) begin  
                y_reg <= y_reg + w[i] * x;  
            end  
            for (i = 0; i < N; i = i + 1) begin  
                w[i] <= w[i] + (STEP_SIZE * e * x);  
            end  
        end  
    end  

    assign y = y_reg;  
endmodule

