module iir_filter(clk, reset, x0, x1, y0, y1, a0, a1, b0, b1);  
    input clk;  
    input reset;  
    input signed [15:0] x0, x1;  
    input signed [15:0] a0, a1, b0, b1;  
    output reg signed [15:0] y0, y1;  

    reg signed [15:0] y_next;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            y0 <= 0;  
            y1 <= 0;  
        end else begin  
            y_next = (b0 * x0 + b1 * x1 + a1 * y0) / a0;  
            y1 <= y0;  
            y0 <= y_next;  
        end  
    end  
endmodule

