module JK_Latch (
    input J,
    input K,
    input clk,
    output reg Q
);
    always @(posedge clk) begin
        if (J && K) 
            Q <= ~Q; // Toggle
        else if (J && !K) 
            Q <= 1; // Set
        else if (!J && K) 
            Q <= 0; // Reset
        // if both J and K are low, Q retains its value
    end
endmodule

