module sample_rate_converter (
    input clk,
    input rst,
    input [7:0] in_sample,
    input in_valid,
    output reg [7:0] out_sample,
    output reg out_valid
);
    reg [1:0] state;
    reg [7:0] sample_buffer;

    parameter IDLE = 2'b00, READ = 2'b01, OUTPUT = 2'b10;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            out_sample <= 8'b0;
            out_valid <= 1'b0;
            sample_buffer <= 8'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in_valid) begin
                        sample_buffer <= in_sample;
                        state <= READ;
                    end
                end
                READ: begin
                    out_sample <= sample_buffer;
                    out_valid <= 1'b1;
                    state <= OUTPUT;
                end
                OUTPUT: begin
                    out_sample <= 8'b0; // Insert zero
                    out_valid <= 1'b1; 
                    state <= IDLE; // Go back to IDLE after output
                end
            endcase
        end
    end
endmodule

