    always @(posedge clk_in or posedge rst) begin
        if (rst) begin
            state <= 2'b00;
            clk_out <= 0;
        end else begin
            state <= ctrl;
            case (state)
                2'b00: clk_out <= clk_out;             // No multiplication
                2'b01: clk_out <= ~clk_out;            // x2 multiplication
                2'b10: clk_out <= ~clk_out;            // x4 multiplication
                2'b11: clk_out <= ~clk_out;            // x8 multiplication
                default: clk_out <= 0;
            endcase
        end
    end
endmodule

